#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
: "${WEB_PORT:=3100}"
if [[ -f .env ]]; then
  set -a
  # .env generated by setup.sh uses shell-safe secrets.
  source .env
  set +a
fi
echo '[1/3] Docker Compose configuration...'
docker compose config -q
echo '[2/3] Container services...'
docker compose ps
echo '[3/3] Health endpoint through Nginx...'
curl -fsS "http://127.0.0.1:${WEB_PORT}/api/health"
echo
